const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`Contrast simple diffusion, facilitated diffusion, and active transport.`]: {
    question: r`An uncharged solute enters cells only until its inside and outside concentrations are equal. Uptake is unaffected when ATP is depleted, but it stops completely when one membrane protein is knocked out. How does the solute cross the membrane?`,
    options: [r`By simple diffusion through the lipid bilayer itself`, r`By facilitated diffusion through a carrier or channel`, r`By primary active transport through an ATP-driven pump`, r`By secondary active transport through a Na⁺ symporter`],
    correctAnswer: 1,
    explanation: r`Movement that stops at equal concentrations is downhill, and needing a protein without needing ATP makes it facilitated diffusion. Simple diffusion would survive the knockout. Either kind of active transport would push the solute past equal concentrations, and a pump would stop when ATP ran out.`,
  },
  [r`How does the $Na^{+}/K^{+}$ ATPase work?`]: {
    question: r`A patch of membrane contains Na⁺/K⁺ ATPase molecules that together complete 100 pump cycles. What has been moved, and what is the net charge transfer?`,
    options: [r`200 Na⁺ out and 300 K⁺ in; net 100 positive charges in`, r`300 Na⁺ out and 300 K⁺ in; no net charge is transferred`, r`300 K⁺ out and 200 Na⁺ in; net 100 positive charges out`, r`300 Na⁺ out and 200 K⁺ in; net 100 positive charges out`],
    correctAnswer: 3,
    explanation: r`Each cycle sends 3 Na⁺ out and brings 2 K⁺ in, so 100 cycles move 300 Na⁺ out and 200 K⁺ in, a net 100 positive charges outward. Swapping the 3 and the 2 reverses the net charge, equal numbers would make the pump electroneutral, and the option with K⁺ leaving has the ions going the wrong way.`,
  },
  [r`What happens to a cell in hypertonic vs. hypotonic solution?`]: {
    question: r`A technician dilutes a sample of red blood cells with a large volume of distilled water instead of isotonic saline. A minute later the suspension is clear red and no intact cells can be found. What happened?`,
    options: [r`Water entered the cells, which swelled until they burst`, r`Water left the cells, which shrank until they crenated`, r`Solute entered the cells, which shrank until they burst`, r`Solute left the cells, which swelled until they crenated`],
    correctAnswer: 0,
    explanation: r`Distilled water is hypotonic to the cytoplasm, so water moves in, the cells swell, and they lyse, releasing hemoglobin. Water leaving and crenation describe a hypertonic solution. The two options about solute movement fail because the water has no solute to give, and they pair swelling or shrinking with the wrong outcome.`,
  },
  [r`Distinguish primary and secondary active transport.`]: {
    question: r`A bacterial carrier brings a sugar into the cell against its concentration gradient while an H⁺ moves inward with it. The carrier has no ATP-binding site, and uptake stops soon after the cell's H⁺ pump is poisoned. How is this carrier classified?`,
    options: [r`Primary active transport, driven by ATP hydrolysis`, r`Facilitated diffusion, driven by the sugar gradient`, r`Secondary active transport, driven by the H⁺ gradient`, r`Simple diffusion, driven by the membrane potential`],
    correctAnswer: 2,
    explanation: r`The sugar moves uphill using energy stored in an H⁺ gradient that a separate pump built, which is secondary active transport. Primary active transport would need the carrier itself to hydrolyze ATP. Facilitated and simple diffusion cannot move a solute against its gradient.`,
  },
  [r`What are tight junctions, desmosomes, and gap junctions?`]: {
    question: r`A small fluorescent dye that cannot cross membranes is injected into one heart muscle cell. Within seconds the dye appears in the cytoplasm of the neighboring cells, without entering the extracellular fluid. Which structure allowed this?`,
    options: [r`Tight junctions, which seal the space between adjacent cells`, r`Gap junctions, which join the cytoplasm of adjacent cells`, r`Desmosomes, which anchor the filaments of adjacent cells`, r`Hemidesmosomes, which anchor cells to the basal lamina`],
    correctAnswer: 1,
    explanation: r`Direct passage from one cytoplasm to the next is the job of gap junctions. Tight junctions block leakage between cells but do not connect their interiors. Desmosomes and hemidesmosomes are mechanical anchors, to a neighbor cell or to the basal lamina, and pass no solutes.`,
  },
  [r`Describe the fluid mosaic model.`]: {
    question: r`A transmembrane protein is tagged on its extracellular domain. Over the next hour the tag spreads across the whole cell surface, but it is never found facing the cytosol. Which statement best fits the fluid mosaic model?`,
    options: [r`The protein diffuses laterally but does not flip across the bilayer`, r`The protein flips across the bilayer but does not diffuse laterally`, r`The protein is fixed in place and the lipids carry the tag around`, r`The protein leaves the bilayer and rebinds at random on either face`],
    correctAnswer: 0,
    explanation: r`In the fluid mosaic model, proteins move sideways within the plane of the bilayer, which spreads the tag, but they keep their orientation because dragging hydrophilic domains through the core is very unfavorable. Flipping would put the tag on the cytosolic side. A fixed protein would not spread, and leaving and rebinding would also scramble the orientation.`,
  },
  [r`What is osmotic pressure?`]: {
    question: r`A 0.10 M NaCl solution is separated from pure water by a membrane permeable only to water. Assume NaCl dissociates completely and RT = 25 L·atm/mol. What pressure must be applied to the solution to stop net water flow?`,
    options: [r`2.5 atm`, r`0.5 atm`, r`5.0 atm`, r`10 atm`],
    correctAnswer: 2,
    explanation: r`The pressure needed is the osmotic pressure, Π = iMRT = 2 × 0.10 × 25 = 5.0 atm. Leaving out the van 't Hoff factor of 2 gives 2.5 atm, a decimal slip gives 0.5 atm, and counting four particles gives 10 atm.`,
  },
  [r`How do endocytosis and exocytosis differ?`]: {
    question: r`A neutrophil wraps its membrane around an antibody-coated bacterium and takes it in inside a large vesicle. Later it fuses granules with its plasma membrane to release enzymes outside the cell. In order, these two events are:`,
    options: [r`pinocytosis, then exocytosis`, r`exocytosis, then phagocytosis`, r`phagocytosis, then pinocytosis`, r`phagocytosis, then exocytosis`],
    correctAnswer: 3,
    explanation: r`Engulfing a large particle into a vesicle is phagocytosis, a form of endocytosis, and fusing granules with the plasma membrane to release their contents is exocytosis. Pinocytosis is uptake of fluid droplets, not a whole bacterium, and it is not a way to release material. The reversed order names the two events backwards.`,
  },
  [r`Osmolarity differs from tonicity because tonicity considers:`]: {
    question: r`Cells whose cytoplasm holds 300 mOsm/L of impermeant solute are placed in a solution of 300 mOsm/L NaCl plus 100 mOsm/L ethanol, which crosses the membrane freely. How is the solution described, and what is the final cell volume?`,
    options: [r`Hyperosmotic and hypertonic; the cells stay shrunken`, r`Hyperosmotic but isotonic; the volume ends up unchanged`, r`Isosmotic and isotonic; the volume never changes at all`, r`Hyperosmotic but hypotonic; the cells swell and burst`],
    correctAnswer: 1,
    explanation: r`Total solute is 400 mOsm/L, so the solution is hyperosmotic, but tonicity counts only the non-penetrating NaCl, 300 mOsm/L, which matches the cell. Ethanol equilibrates across the membrane and exerts no lasting pull, so the volume returns to normal. Calling it hypertonic counts ethanol as an effective solute, calling it isosmotic ignores ethanol, and hypotonic would need less than 300 mOsm/L of impermeant solute.`,
  },
  [r`The glycocalyx functions in:`]: {
    question: r`Cultured white blood cells are treated with an enzyme that strips the carbohydrate chains from their surface proteins and lipids. Which ability of the cells is lost most directly?`,
    options: [r`Keeping their bilayer fluid when chilled`, r`Pumping Na⁺ out against its gradient`, r`Being recognized and bound by other cells`, r`Passing ions directly to adjacent cells`],
    correctAnswer: 2,
    explanation: r`The surface carbohydrate coat, the glycocalyx, serves cell recognition and adhesion, so removing it stops other cells from identifying and binding these cells. Fluidity is set by lipid tails and cholesterol, Na⁺ pumping by the Na⁺/K⁺ ATPase, and direct ion passage by gap junctions.`,
  },
  [r`Which describes secondary active transport?`]: {
    question: r`A newly cloned transporter is being characterized. Which observation would show that it carries out secondary active transport?`,
    options: [r`It moves its solute uphill only while a Na⁺ gradient is present`, r`It moves its solute uphill only while it is hydrolyzing ATP`, r`It moves its solute downhill and saturates at high levels`, r`It moves its solute downhill at a rate that never saturates`],
    correctAnswer: 0,
    explanation: r`Secondary active transport moves a solute uphill using an ion gradient that a primary pump established, so it works only while that gradient exists. Uphill movement tied to the transporter's own ATP hydrolysis is primary active transport. Downhill movement with saturation is facilitated diffusion, and without saturation it is simple diffusion.`,
  },
  [r`Integral membrane proteins are characterized by:`]: {
    question: r`Sequence analysis of a new membrane-associated protein shows seven separate stretches of about 20 hydrophobic residues, each predicted to form an α-helix. The protein is most likely:`,
    options: [r`a peripheral protein bound to seven lipid head groups`, r`a secreted protein that folds around seven lipid tails`, r`an anchored protein held by seven GPI lipid linkages`, r`an integral protein that crosses the bilayer seven times`],
    correctAnswer: 3,
    explanation: r`A stretch of about 20 hydrophobic residues in an α-helix is the right length and character to span the bilayer core, so seven of them indicate an integral protein with seven transmembrane domains. Peripheral proteins sit on the surface and lack such domains. A secreted protein is soluble, and GPI anchors are attached lipids, not hydrophobic helices.`,
  },
  [r`During oxidative phosphorylation, the final electron acceptor in the electron transport chain is:`]: {
    question: r`Respiring mitochondria are suddenly deprived of O₂ while NADH is still plentiful. What happens to the electron transport chain?`,
    options: [r`Carriers stay oxidized and flow stops, as no donor remains`, r`Carriers stay reduced and flow stops, as no acceptor remains`, r`Flow continues, with NAD⁺ now taking the electrons at the end`, r`Flow continues, with H₂O now taking the electrons at the end`],
    correctAnswer: 1,
    explanation: r`O₂ is the final electron acceptor, taking electrons from Complex IV to form water. Without it, electrons back up, every carrier stays reduced, and flow stops. Carriers would be stuck oxidized only if the donor, NADH, ran out. NAD⁺ and water cannot stand in for O₂ as the terminal acceptor: water is the product, not an acceptor.`,
  },
  [r`Which membrane is impermeable to most ions, creating the proton gradient?`]: {
    question: r`Mitochondria are stripped of their outer membrane, leaving the inner membrane and matrix intact. Given substrate, O₂, ADP and phosphate, they still build a proton gradient and make ATP. What does this show?`,
    options: [r`The inner membrane is the ion-tight barrier that holds the gradient`, r`The outer membrane is the ion-tight barrier that holds the gradient`, r`The gradient is held across the matrix, not across any membrane`, r`The inner membrane has porins that let protons cross both ways`],
    correctAnswer: 0,
    explanation: r`A gradient that survives removal of the outer membrane must be held by the inner membrane, which is impermeable to most ions. The outer membrane has porins and is freely permeable to small molecules, so it could not hold protons. A gradient needs a membrane to separate two compartments, and porins in the inner membrane would collapse it.`,
  },
  [r`The endosymbiotic theory proposes that mitochondria evolved from:`]: {
    question: r`An antibiotic blocks bacterial-type ribosomes but not eukaryotic cytosolic ribosomes. Based on the origin of organelles, which process in a human cell is it most likely to disturb as a side effect?`,
    options: [r`Translation on ribosomes bound to the rough ER`, r`Translation on free ribosomes in the cytosol`, r`Translation on ribosomes inside the mitochondria`, r`Transcription by RNA polymerase in the nucleus`],
    correctAnswer: 2,
    explanation: r`Mitochondria descend from aerobic prokaryotes and still carry bacterial-type ribosomes, so a drug aimed at bacterial ribosomes can hit mitochondrial translation. Ribosomes on the rough ER and free in the cytosol are the eukaryotic type that the drug spares. Nuclear transcription does not use ribosomes at all.`,
  },
  [r`In the renal collecting duct, {{c1::vasopressin (ADH)}} raises water permeability by driving {{c2::aquaporin-2}} insertion into the apical membrane.`]: {
    question: r`A hiker goes a full day without water, and vasopressin (ADH) levels rise. What change occurs in the principal cells of the collecting duct?`,
    options: [r`Aquaporin-2 moves from the apical membrane into vesicles`, r`Aquaporin-2 moves from vesicles into the basolateral membrane`, r`Aquaporin-3 moves from the basolateral membrane into vesicles`, r`Aquaporin-2 moves from vesicles into the apical membrane`],
    correctAnswer: 3,
    explanation: r`ADH drives insertion of aquaporin-2 into the apical membrane, raising water permeability so water is reabsorbed and urine is concentrated. Removal from the apical membrane is what happens when ADH falls. The regulated step is apical, not basolateral, and the basolateral aquaporins are always present and are not withdrawn.`,
  },
  [r`Transporter classes: {{c1::uniporters}} move one solute (GLUT1); {{c2::symporters}} couple two in the same direction (SGLT1); antiporters swap them (NCX).`]: {
    question: r`Transporter P moves one Na⁺ and one phosphate ion into the cell together on each cycle. Transporter Q moves fructose alone, down its concentration gradient. How are P and Q classified?`,
    options: [r`P is a symporter and Q is a uniporter`, r`P is an antiporter and Q is a uniporter`, r`P is a uniporter and Q is a symporter`, r`P is a symporter and Q is an antiporter`],
    correctAnswer: 0,
    explanation: r`Two solutes carried in the same direction make P a symporter, and a single solute moving down its gradient makes Q a uniporter. An antiporter would move its two solutes in opposite directions, which neither transporter does. Calling P a uniporter ignores that it carries two solutes.`,
  },
  [r`SGLT1 moves glucose {{c1::against}} its gradient by coupling it to {{c2::Na+}} flowing downhill — apical membrane of intestine and proximal tubule.`]: {
    question: r`Late in digestion the glucose concentration in the gut lumen is 1 mM, while it is 5 mM inside the enterocytes. Glucose still enters the cells across the apical membrane. What makes this possible?`,
    options: [r`ATP is split by the glucose carrier on each cycle`, r`K⁺ moves down its gradient through the same carrier`, r`Na⁺ moves down its gradient through the same carrier`, r`Glucose moves down its gradient through the carrier`],
    correctAnswer: 2,
    explanation: r`SGLT1 couples glucose entry to Na⁺ entry, and the steep inward Na⁺ gradient pays for moving glucose uphill. The carrier does not hydrolyze ATP itself. K⁺ is not the coupled ion, and glucose here is moving against its gradient, from 1 mM to 5 mM.`,
  },
  [r`Resting membrane potential lies closest to $E_{K}$ because the resting membrane is most permeable to {{c1::K+}} through leak channels.`]: {
    question: r`A toxin closes most of a neuron's K⁺ leak channels and leaves every other channel and pump unchanged. What happens to the resting membrane potential?`,
    options: [r`It becomes more negative, since K⁺ can no longer leave the cell`, r`It becomes less negative, since the Na⁺ leak now carries more weight`, r`It stays the same, since the Na⁺/K⁺ pump alone sets the potential`, r`It becomes more negative, since it moves closer to the K⁺ potential`],
    correctAnswer: 1,
    explanation: r`The resting potential sits near the K⁺ equilibrium potential only because K⁺ permeability dominates. Lowering it gives the small Na⁺ leak more weight, so the potential shifts toward the Na⁺ equilibrium potential and becomes less negative. K⁺ leaving is what makes the inside negative, so blocking it cannot hyperpolarize, and the pump contributes only a few millivolts directly.`,
  },
  [r`GLUT{{c1::4}} is the insulin-responsive transporter of muscle and adipose; GLUT{{c2::2}} is the high-Km glucose sensor of liver and pancreatic beta cells.`]: {
    question: r`Insulin is injected into a fasting animal. In which tissue does glucose uptake rise most because transporters are newly inserted into the plasma membrane, and which transporter is it?`,
    options: [r`Skeletal muscle, by insertion of GLUT2`, r`Liver, by insertion of GLUT4`, r`Brain, by insertion of GLUT1`, r`Skeletal muscle, by insertion of GLUT4`],
    correctAnswer: 3,
    explanation: r`GLUT4 is the insulin-responsive transporter of muscle and adipose tissue: insulin makes its storage vesicles fuse with the plasma membrane. GLUT2 is the high-Km transporter of liver and beta cells and is not moved by insulin, and the liver does not rely on GLUT4. Brain GLUT1 supplies glucose at a steady rate that does not depend on insulin.`,
  },
  [r`How do the kinetics of carrier-mediated (facilitated) transport differ from simple diffusion?`]: {
    question: r`When the external concentration is doubled from 50 mM to 100 mM, uptake of solute A changes from 98 to 99 units, while uptake of solute B changes from 40 to 80 units. What do these results indicate?`,
    options: [r`A uses a carrier that is nearly saturated; B crosses by simple diffusion`, r`A crosses by simple diffusion; B uses a carrier that is nearly saturated`, r`A and B both use carriers, and both are working far below saturation`, r`A and B both cross by simple diffusion, but A has the smaller gradient`],
    correctAnswer: 0,
    explanation: r`Uptake of A has reached a plateau, the sign of a carrier with nearly all sites occupied. Uptake of B doubles when concentration doubles, the linear behavior of simple diffusion. The reversed assignment mixes up the two patterns, a carrier far below saturation would not be flat as A is, and simple diffusion never levels off.`,
  },
  [r`150 mM NaCl has an osmolarity of about {{c1::300}} mOsm/L (van 't Hoff factor 2), roughly isotonic to plasma.`]: {
    question: r`A solution contains 100 mM NaCl and 100 mM glucose. Assuming NaCl dissociates completely, what is its osmolarity, and how does it compare with plasma at about 290 mOsm/L?`,
    options: [r`About 200 mOsm/L, clearly hyposmotic`, r`About 400 mOsm/L, clearly hyperosmotic`, r`About 300 mOsm/L, roughly isosmotic`, r`About 150 mOsm/L, clearly hyposmotic`],
    correctAnswer: 2,
    explanation: r`NaCl contributes 2 particles per formula unit, so 100 mM gives 200 mOsm/L, and glucose adds 100 mOsm/L, for a total near 300 mOsm/L. Counting NaCl as one particle gives 200, counting glucose as two particles gives 400, and 150 comes from halving instead of doubling the NaCl.`,
  },
  [r`Why is 300 mM urea isosmotic yet hypotonic to a red blood cell?`]: {
    question: r`Red blood cells are added to four solutions, each about 300 mOsm/L. In which one will the cells swell and lyse?`,
    options: [r`150 mM NaCl`, r`300 mM urea`, r`300 mM sucrose`, r`100 mM CaCl₂`],
    correctAnswer: 1,
    explanation: r`Urea crosses the red cell membrane, so it is not an effective osmole: it equilibrates, water follows it in, and the cells lyse even though the solution is isosmotic. NaCl, sucrose and CaCl₂ do not penetrate, so at about 300 mOsm/L each is isotonic and the cells keep their volume.`,
  },
  [r`Compare SGLT1 and SGLT2 in stoichiometry, location, and clinical relevance.`]: {
    question: r`A diabetes drug blocks a high-capacity transporter in the early proximal tubule that carries 1 Na⁺ with each glucose. Which transporter is blocked, and what is the main result?`,
    options: [r`SGLT1; glucose is lost in the urine`, r`SGLT2; glucose is lost in the stool`, r`SGLT1; glucose is lost in the stool`, r`SGLT2; glucose is lost in the urine`],
    correctAnswer: 3,
    explanation: r`The early proximal tubule transporter with 1 Na⁺ per glucose is SGLT2, which normally reabsorbs about 90 percent of filtered glucose, so blocking it causes glucosuria. SGLT1 uses 2 Na⁺ per glucose and works in the late proximal tubule and intestine. Loss in the stool would follow from blocking intestinal SGLT1, not a renal transporter.`,
  },
  [r`Why does inhibiting the Na+/K+ ATPase eventually make cells swell and lyse?`]: {
    question: r`During a heart attack, cardiac cells run out of ATP and their Na⁺/K⁺ pumps stop. The cells then swell. Which sequence explains the swelling?`,
    options: [r`Na⁺ leaks in and is not removed, so water follows it inward`, r`K⁺ leaks in and is not removed, so water follows it inward`, r`Impermeant anions leak out, so water enters to replace them`, r`Na⁺ leaks out and is not replaced, so water moves outward`],
    correctAnswer: 0,
    explanation: r`The pump normally offsets the osmotic pull of trapped intracellular anions by keeping Na⁺ out. When it stops, Na⁺ leaks in down its gradient, intracellular solute rises, and water follows until the cell swells. K⁺ leaks out, not in, the impermeant anions cannot leave, and Na⁺ moves inward, not outward.`,
  },
  [r`How do ionophores like valinomycin and uncouplers like DNP dissipate gradients differently?`]: {
    question: r`Dinitrophenol (DNP) is added to actively respiring mitochondria. Which set of changes follows?`,
    options: [r`O₂ use falls, ATP synthesis falls, and less heat is released`, r`O₂ use rises, ATP synthesis rises, and more heat is released`, r`O₂ use rises, ATP synthesis falls, and more heat is released`, r`O₂ use falls, ATP synthesis rises, and less heat is released`],
    correctAnswer: 2,
    explanation: r`DNP carries protons across the inner membrane, so the gradient is spent without passing through ATP synthase. Electron transport speeds up to rebuild it, raising O₂ use, while ATP synthesis falls and the energy appears as heat. Falling O₂ use describes a blocked chain, and ATP synthesis cannot rise when the proton gradient is being short-circuited.`,
  },
  [r`The thick ascending limb reabsorbs salt via the {{c1::Na+-K+-2Cl- (NKCC2)}} symporter, target of {{c2::loop}} diuretics.`]: {
    question: r`A diuretic blocks an apical carrier that moves 1 Na⁺, 1 K⁺ and 2 Cl⁻ into the tubule cell together. Where does this carrier act, and what class of drug is it?`,
    options: [r`Distal convoluted tubule; a thiazide`, r`Thick ascending limb; a loop diuretic`, r`Cortical collecting duct; amiloride`, r`Early proximal tubule; acetazolamide`],
    correctAnswer: 1,
    explanation: r`The Na⁺-K⁺-2Cl⁻ symporter NKCC2 sits in the thick ascending limb and is the target of loop diuretics such as furosemide. Thiazides block the NaCl cotransporter of the distal tubule, amiloride blocks the Na⁺ channel of the collecting duct, and acetazolamide inhibits carbonic anhydrase in the proximal tubule.`,
  },
  [r`What is transcytosis, and where is it physiologically important?`]: {
    question: r`Maternal IgG is taken up in vesicles on the maternal side of a placental cell, carried across the cytoplasm still inside vesicles, and released on the fetal side. What is this route called?`,
    options: [r`Paracellular leak between cells`, r`Facilitated diffusion by a carrier`, r`Simple diffusion across the cell`, r`Transcytosis through the cell`],
    correctAnswer: 3,
    explanation: r`Endocytosis at one face, vesicle transport across the cell, and exocytosis at the opposite face together make up transcytosis. A paracellular route would pass between cells, not through vesicles. Facilitated and simple diffusion involve no vesicles, and a protein as large as IgG cannot cross membranes that way.`,
  },
  [r`How does the thyroid concentrate iodide?`]: {
    question: r`Thyroid cells normally hold iodide at about 30 times the plasma level. The cells are moved to a bath in which Na⁺ is replaced by an impermeant cation, with ATP supply unchanged. What happens to iodide accumulation?`,
    options: [r`It fails, since the iodide symporter needs Na⁺ flowing inward`, r`It continues, since the iodide symporter splits ATP directly`, r`It rises, since iodide no longer competes with Na⁺ for entry`, r`It fails, since the iodide symporter needs K⁺ flowing outward`],
    correctAnswer: 0,
    explanation: r`The Na⁺/I⁻ symporter moves iodide uphill by coupling it to 2 Na⁺ moving down their gradient, so without external Na⁺ there is nothing to drive uptake. The symporter does not use ATP itself. Na⁺ and iodide travel together, not as competitors, and K⁺ is not the coupled ion.`,
  },
  [r`Trace transcellular glucose absorption across an enterocyte, naming the transporter and energetics at each membrane.`]: {
    question: r`A patient lacks functional GLUT2 in the basolateral membrane of the enterocytes, while SGLT1 and the Na⁺/K⁺ ATPase are normal. What happens to dietary glucose?`,
    options: [r`It cannot enter the cell from the lumen and so stays in the gut`, r`It enters the cell and leaves to the blood through the Na⁺/K⁺ ATPase`, r`It enters the cell from the lumen but cannot leave toward the blood`, r`It crosses the epithelium normally by passing back through SGLT1`],
    correctAnswer: 2,
    explanation: r`Apical SGLT1 still loads glucose into the cell with Na⁺, but the basolateral exit step, facilitated diffusion through GLUT2, is missing, so glucose is trapped. Entry is not the blocked step. The Na⁺/K⁺ ATPase carries only Na⁺ and K⁺, and SGLT1 sits on the apical side and cannot deliver glucose to the blood.`,
  },
  [r`Typical neuronal equilibrium potentials: $E_{K} \approx$ {{c1::-90}} mV and $E_{Na} \approx$ {{c2::+60}} mV.`]: {
    question: r`In a neuron resting at -70 mV, a large number of channels selective for one ion open, and the membrane potential moves to about +55 mV. Which ion do these channels pass?`,
    options: [r`K⁺`, r`Na⁺`, r`Cl⁻`, r`H⁺`],
    correctAnswer: 1,
    explanation: r`Opening a channel drives the membrane potential toward that ion's equilibrium potential, and only Na⁺, at about +60 mV, has a value near +55 mV. K⁺ would pull the potential toward about -90 mV and Cl⁻ would hold it near -70 mV. H⁺ is not a major current carrier in neuronal signaling.`,
  },
  [r`Hyperkalemia {{c1::depolarizes}} the resting membrane because raising extracellular K+ makes $E_{K}$ {{c2::less negative}}.`]: {
    question: r`A cell has $E_{K}$ = -90 mV when the bathing solution contains 5 mM K⁺. The bath K⁺ is raised to 50 mM. Using 61 mV per tenfold concentration change, what is the new $E_{K}$ and the effect on the resting cell?`,
    options: [r`About -151 mV; the cell hyperpolarizes`, r`About -29 mV; the cell hyperpolarizes`, r`About -151 mV; the cell depolarizes`, r`About -29 mV; the cell depolarizes`],
    correctAnswer: 3,
    explanation: r`A tenfold rise in outside K⁺ shifts the K⁺ equilibrium potential 61 mV in the positive direction, from -90 to about -29 mV, and the resting potential follows it, so the cell depolarizes. The -151 mV answers move the potential the wrong way, as if inside K⁺ had been raised. A less negative potential is a depolarization, not a hyperpolarization.`,
  },
  [r`Define the driving force on an ion and use it to predict Ca2+ movement through an open channel at rest.`]: {
    question: r`A cell sits at a membrane potential of -50 mV, with $E_{K}$ = -90 mV and $E_{Na}$ = +60 mV. Which ion has the larger driving force, and in which direction does it tend to move through an open channel?`,
    options: [r`Na⁺, with 110 mV, moving into the cell`, r`K⁺, with 140 mV, moving out of the cell`, r`Na⁺, with 110 mV, moving out of the cell`, r`K⁺, with 40 mV, moving into the cell`],
    correctAnswer: 0,
    explanation: r`Driving force is the membrane potential minus the equilibrium potential: for Na⁺ it is -50 - 60 = -110 mV, an inward push, and for K⁺ it is -50 - (-90) = +40 mV, an outward push. The 140 mV figure adds the two numbers instead of subtracting. Na⁺ flow carries the potential toward +60 mV, which requires entry, and K⁺ leaves rather than enters.`,
  },
  [r`Depolarization means Vm becomes {{c1::less negative}}; opening Cl- channels near rest mainly {{c2::stabilizes}} Vm rather than changing it.`]: {
    question: r`In a neuron resting at -70 mV with $E_{Cl}$ = -70 mV, GABA opens many Cl⁻ channels. An excitatory input that used to bring the cell to -55 mV arrives at the same moment. What is observed?`,
    options: [r`GABA alone moves the potential to -90 mV, and the excitatory rise is equal`, r`GABA alone moves the potential to -55 mV, and the excitatory rise is larger`, r`GABA alone barely moves the potential, and the excitatory rise is smaller`, r`GABA alone barely moves the potential, and the excitatory rise is the same`],
    correctAnswer: 2,
    explanation: r`With the Cl⁻ equilibrium potential at the resting value, opening Cl⁻ channels changes the voltage little but holds it there: any depolarization draws Cl⁻ in, which opposes it. So the excitatory input depolarizes the cell less. A move to -90 mV would need K⁺ channels, a move to -55 mV would be a depolarization that Cl⁻ cannot cause here, and an unchanged excitatory response ignores the stabilizing effect.`,
  },
  [r`Osmotic pressure is colligative. What does $\pi = iMRT$ imply when comparing solutions across a membrane?`]: {
    question: r`A membrane permeable only to water separates side A, 0.30 M glucose, from side B, 0.15 M MgCl₂. Assuming MgCl₂ dissociates completely, which way does water flow?`,
    options: [r`Toward A, since A has the higher molarity`, r`Toward B, since B holds 0.45 M of particles`, r`Toward B, since ions pull harder than sugar`, r`No net flow, since 0.15 M × 2 equals 0.30 M`],
    correctAnswer: 1,
    explanation: r`Osmotic pressure depends on total particle concentration: MgCl₂ gives 3 particles, so side B is 0.45 M in particles against 0.30 M on side A, and water moves toward B. Comparing molarity alone ignores dissociation. Particle identity does not matter for a colligative property, and the no-flow answer counts only 2 particles per MgCl₂.`,
  },
  [r`Why does ouabain poisoning stop secondary active transport, even though those transporters use no ATP?`]: {
    question: r`In a kidney tubule cell, the Na⁺/H⁺ exchanger uses no ATP. After an hour of ouabain treatment it has nearly stopped exporting H⁺. Why?`,
    options: [r`Ouabain binds the exchanger and blocks its Na⁺ site`, r`The exchanger hydrolyzes ATP that ouabain has depleted`, r`The H⁺ gradient that powers the exchanger has run down`, r`The Na⁺ gradient that powers the exchanger has run down`],
    correctAnswer: 3,
    explanation: r`Ouabain blocks the Na⁺/K⁺ ATPase, so the inward Na⁺ gradient decays, and every Na⁺-coupled carrier, including the exchanger, loses its energy source. Ouabain does not act on the exchanger directly, and the exchanger never hydrolyzes ATP. The exchanger is driven by the Na⁺ gradient and moves H⁺ uphill, so H⁺ is not its power source.`,
  },
  [r`A cell rests at Vm = -70 mV and has $E_{Cl} = -70$ mV. What is the net Cl- flux through open Cl- channels?`]: {
    question: r`A cell has 100 mM Cl⁻ outside and 10 mM Cl⁻ inside. Using 61 mV per tenfold concentration ratio, at what membrane potential is there no net Cl⁻ flux through open Cl⁻ channels?`,
    options: [r`-61 mV`, r`+61 mV`, r`-30 mV`, r`0 mV`],
    correctAnswer: 0,
    explanation: r`Net flux is zero when the membrane potential equals the Cl⁻ equilibrium potential. For an anion ten times more concentrated outside, the inside must be negative by 61 mV to push Cl⁻ out as hard as the gradient pushes it in. +61 mV uses the sign for a cation, -30 mV halves the value as if the ion were divalent, and 0 mV ignores the concentration gradient.`,
  },
  [r`What do ABC transporters do? Name two medically important members with different mechanisms.`]: {
    question: r`Two ABC proteins are studied. Protein A uses ATP hydrolysis to expel a hydrophobic drug from the cell against its gradient. Protein B uses ATP to open a pore through which Cl⁻ flows down its electrochemical gradient. Which identification fits?`,
    options: [r`A is CFTR and B is P-glycoprotein`, r`A is P-glycoprotein and B is ENaC`, r`A is P-glycoprotein and B is CFTR`, r`A is SERCA and B is CFTR`],
    correctAnswer: 2,
    explanation: r`P-glycoprotein (MDR1) is the ABC pump that exports hydrophobic drugs, and CFTR is the unusual ABC protein that works as an ATP-gated Cl⁻ channel. The reversed answer swaps the two mechanisms. ENaC is a Na⁺ channel and SERCA is a P-type Ca²⁺ pump, and neither belongs to the ABC family.`,
  },
  [r`Distinguish P-type, V-type, and F-type ATPases with an example of each.`]: {
    question: r`A drug stops lysosomes from reaching their normal acidic pH, while the Na⁺/K⁺ ATPase and mitochondrial ATP synthesis continue normally. Which protein does the drug inhibit?`,
    options: [r`A P-type H⁺ ATPase`, r`A V-type H⁺ ATPase`, r`An F-type ATP synthase`, r`An ABC-type exporter`],
    correctAnswer: 1,
    explanation: r`Organelles such as lysosomes are acidified by V-type H⁺ ATPases. P-type pumps, which include the Na⁺/K⁺ ATPase and the gastric H⁺/K⁺ ATPase, work at other membranes, and the Na⁺/K⁺ ATPase was unaffected here. The F-type enzyme makes ATP in mitochondria and was also unaffected, and ABC exporters do not acidify lysosomes.`,
  },
  [r`The Na+/H+ exchanger (NHE) is an electroneutral antiporter regulating intracellular {{c1::pH}} and reabsorbing Na+ in the {{c2::proximal tubule}}.`]: {
    question: r`Cells are loaded with acid, and their cytosolic pH recovers within minutes. Recovery fails when Na⁺ is removed from the bath, and it involves no net movement of charge. Which transporter is responsible, and what does it move?`,
    options: [r`The Na⁺/H⁺ exchanger: 1 Na⁺ out for 1 H⁺ in`, r`The Na⁺/Ca²⁺ exchanger: 3 Na⁺ in for 1 Ca²⁺ out`, r`The H⁺/K⁺ ATPase: 1 H⁺ out for 1 K⁺ in`, r`The Na⁺/H⁺ exchanger: 1 Na⁺ in for 1 H⁺ out`],
    correctAnswer: 3,
    explanation: r`The Na⁺/H⁺ exchanger uses the inward Na⁺ gradient to export H⁺ one for one, which raises cytosolic pH, needs external Na⁺, and moves no net charge. Running it the other way would acidify the cell. The Na⁺/Ca²⁺ exchanger moves no H⁺ and is electrogenic, and the H⁺/K⁺ ATPase does not depend on external Na⁺.`,
  },
  [r`What makes a transporter electrogenic versus electroneutral? Classify NCX, NHE, and AE1.`]: {
    question: r`Four transport cycles are listed. Which one is electroneutral?`,
    options: [r`1 Na⁺ in together with 1 Cl⁻ in`, r`2 Na⁺ in together with 1 glucose in`, r`3 Na⁺ in exchanged for 1 Ca²⁺ out`, r`3 Na⁺ out exchanged for 2 K⁺ in`],
    correctAnswer: 0,
    explanation: r`One positive and one negative charge entering together carry no net charge, so the Na⁺ and Cl⁻ cotransport is electroneutral. Two Na⁺ with uncharged glucose bring in two positive charges. Three Na⁺ in for one Ca²⁺ out is a net +1 inward, and three Na⁺ out for two K⁺ in is a net +1 outward, so both are electrogenic.`,
  },
  [r`What distinguishes primary from secondary active transport? Give an example of each.`]: {
    question: r`A cardiac cell removes cytosolic Ca²⁺ with two transporters: SERCA and the Na⁺/Ca²⁺ exchanger. ATP hydrolysis is suddenly blocked while the Na⁺ gradient is still intact. What happens in the first few seconds?`,
    options: [r`The exchanger stops at once; SERCA keeps working for now`, r`Both stop at once, since both of them hydrolyze ATP`, r`SERCA stops at once; the exchanger keeps working for now`, r`Both keep working, since neither one hydrolyzes ATP`],
    correctAnswer: 2,
    explanation: r`SERCA is a primary active transporter that hydrolyzes ATP itself, so it stops immediately. The Na⁺/Ca²⁺ exchanger is secondary active: it spends the Na⁺ gradient and keeps running until that gradient decays. The reversed answer swaps the two classes, and the last two treat both transporters as the same type.`,
  },
  [r`What is the chloride shift, and which transporter performs it?`]: {
    question: r`As blood passes through the lung capillaries, CO₂ is being released from the blood. What does the red cell Cl⁻/HCO₃⁻ exchanger (AE1) do there?`,
    options: [r`It sends HCO₃⁻ out of the cell and brings Cl⁻ in`, r`It brings HCO₃⁻ into the cell and sends Cl⁻ out`, r`It brings both HCO₃⁻ and Cl⁻ into the cell`, r`It sends both HCO₃⁻ and Cl⁻ out of the cell`],
    correctAnswer: 1,
    explanation: r`In the tissues AE1 exports HCO₃⁻ in exchange for Cl⁻; in the lungs the exchange reverses, so HCO₃⁻ re-enters the red cell to be converted back to CO₂ and Cl⁻ leaves. Sending HCO₃⁻ out describes the tissue capillaries. AE1 is an antiporter, so it never moves both ions in the same direction.`,
  },
  [r`Gastric parietal cells secrete acid with the {{c1::H+/K+ ATPase}}, a P-type primary pump and the target of proton pump inhibitors.`]: {
    question: r`In an isolated stomach preparation, the fluid bathing the luminal side is replaced with one that contains no K⁺. Parietal cells are stimulated and have plenty of ATP. What happens to acid secretion?`,
    options: [r`It continues, because the pump exchanges H⁺ for Na⁺`, r`It stops, because a K⁺ gradient is the pump's energy source`, r`It continues, because the pump moves H⁺ with no partner`, r`It stops, because the pump exchanges H⁺ for luminal K⁺`],
    correctAnswer: 3,
    explanation: r`The gastric H⁺/K⁺ ATPase is a primary pump that trades each cytosolic H⁺ for a luminal K⁺, so with no K⁺ in the lumen it cannot complete its cycle. Na⁺ is not its exchange partner, and H⁺ is not moved alone. Its energy comes from ATP hydrolysis, not from a K⁺ gradient.`,
  },
  [r`Why does a tenfold Ca2+ gradient produce only about 30 mV of equilibrium potential while the same Na+ gradient gives about 61 mV?`]: {
    question: r`A cell has 1 mM free Ca²⁺ outside and 0.0001 mM inside. Using 61 mV per tenfold ratio for a monovalent ion at body temperature, what is the Ca²⁺ equilibrium potential?`,
    options: [r`About +122 mV`, r`About +244 mV`, r`About -122 mV`, r`About +61 mV`],
    correctAnswer: 0,
    explanation: r`The ratio is 10⁴, four tenfold steps, and a divalent ion gains 61/2 = 30.5 mV per step, so the potential is about 4 × 30.5 = +122 mV. Using 61 mV per step forgets the valence and gives +244 mV. The negative value flips the ratio, and +61 mV counts only two of the four tenfold steps at 30.5 mV each.`,
  },
  [r`In Goldman (GHK) terms, what happens to Vm when ACh opens nicotinic channels permeable to both Na+ and K+?`]: {
    question: r`At a muscle end plate resting at -70 mV, acetylcholine opens channels about equally permeable to Na⁺ and K⁺. With $E_{Na}$ = +60 mV and $E_{K}$ = -90 mV, toward what value does the end-plate membrane move while they are open?`,
    options: [r`Roughly +60 mV, a depolarization`, r`Roughly -90 mV, a hyperpolarization`, r`Roughly -15 mV, a depolarization`, r`Roughly -80 mV, a hyperpolarization`],
    correctAnswer: 2,
    explanation: r`The membrane potential moves toward a permeability-weighted average of the equilibrium potentials of the permeant ions. With equal weights that is about midway between +60 and -90 mV, near -15 mV, a strong depolarization from -70 mV. +60 mV would need Na⁺ permeability alone, -90 mV would need K⁺ alone, and -80 mV averages the resting potential with the K⁺ value.`,
  },
  [r`Why do red blood cells and the blood-brain barrier rely on GLUT1?`]: {
    question: r`GLUT1 has a Km for glucose of about 1 mM. After a meal, blood glucose rises from 5 mM to 10 mM. What happens to glucose entry into red blood cells through GLUT1?`,
    options: [r`It roughly doubles, as entry is proportional to blood glucose`, r`It rises only slightly, as GLUT1 was already near saturation`, r`It rises several fold, as insulin adds GLUT1 to the membrane`, r`It falls slightly, as excess glucose inhibits its own carrier`],
    correctAnswer: 1,
    explanation: r`With a Km of 1 mM, GLUT1 runs at about 5/6 of its maximum at 5 mM and about 10/11 at 10 mM, so entry barely changes. Doubling would be expected for a high-Km carrier such as GLUT2. Insulin recruits GLUT4, not GLUT1, and more substrate does not slow a saturable carrier.`,
  },
  [r`Predict red cell shape in 100 mM NaCl versus 400 mM NaCl, and name each response.`]: {
    question: r`Red blood cells are placed in 200 mM NaCl. Assuming complete dissociation and a cell interior of about 300 mOsm/L, what happens to the cells?`,
    options: [r`They swell and may lyse, as the solution is about 200 mOsm/L`, r`They keep their shape, as the solution is about 300 mOsm/L`, r`They swell and may lyse, as NaCl enters and water follows it`, r`They shrink and crenate, as the solution is about 400 mOsm/L`],
    correctAnswer: 3,
    explanation: r`Each NaCl gives two particles, so 200 mM NaCl is about 400 mOsm/L, hypertonic to the cell: water leaves and the cell shrivels into a spiky, crenated shape. Reading 200 mM as 200 mOsm/L forgets dissociation and wrongly predicts swelling. The solution is not 300 mOsm/L, and NaCl does not penetrate the red cell membrane.`,
  },
  [r`Two membranes share head groups but differ in melting behavior. Which acyl chain features predict the more fluid one?`]: {
    question: r`Bacteria grown at 37 °C are shifted to 15 °C. To keep their membranes as fluid as before, how should the acyl chains of their phospholipids change?`,
    options: [r`More cis double bonds and shorter chains`, r`More cis double bonds and longer chains`, r`Fewer cis double bonds and shorter chains`, r`Fewer cis double bonds and longer chains`],
    correctAnswer: 0,
    explanation: r`Cold makes chains pack tightly, so the cell must weaken packing: cis double bonds add kinks and shorter chains have less surface contact, and both raise fluidity. Longer chains pack more strongly, and fewer double bonds mean straighter chains. Either of those changes would stiffen a membrane that the cold has already stiffened.`,
  },
  [r`Rank O2, water, glucose, and Na+ by permeability through a pure lipid bilayer, and state what sets the order.`]: {
    question: r`K⁺ is much smaller than glucose, yet it crosses a protein-free lipid bilayer far more slowly. What is the main reason?`,
    options: [r`Its small size lets it slip back out before crossing the core`, r`Its concentration gradient is always smaller than that of glucose`, r`Its charge and hydration shell keep it out of the nonpolar core`, r`Its positive charge is repelled by the fatty acid tails in the core`],
    correctAnswer: 2,
    explanation: r`A charged ion with its shell of water is extremely unfavorable in the nonpolar interior of the bilayer, so charge outweighs size in setting permeability. Small size would help, not hinder, crossing. The comparison holds at equal gradients, and fatty acid tails are uncharged, so they do not repel a cation electrostatically.`,
  },
  [r`Typical gradients: K+ is about {{c1::140}} mM inside versus 4 mM outside, while Na+ is about 145 mM outside versus {{c2::12}} mM inside.`]: {
    question: r`A fluid sample from a healthy animal contains 140 mM K⁺ and 12 mM Na⁺. Where was it most likely taken from?`,
    options: [r`The plasma of arterial blood`, r`The cytosol of a typical cell`, r`The interstitial fluid of muscle`, r`The filtrate of a glomerulus`],
    correctAnswer: 1,
    explanation: r`High K⁺, about 140 mM, with low Na⁺, about 12 mM, is the profile of cytosol, maintained by the Na⁺/K⁺ pump. Plasma, interstitial fluid and glomerular filtrate are all extracellular fluids, with about 145 mM Na⁺ and only about 4 mM K⁺.`,
  },
  [r`Cholera causes massive watery diarrhea, yet oral rehydration solution containing glucose and salt works. What transport logic explains both?`]: {
    question: r`Intestinal tissue from mice that completely lack CFTR is exposed to cholera toxin, and cAMP rises as usual. What happens to fluid secretion into the lumen?`,
    options: [r`Massive secretion, since cAMP alone drives water out`, r`Little secretion, since the toxin now blocks SGLT1`, r`Massive secretion, since Na⁺ exits through SGLT1`, r`Little secretion, since the Cl⁻ exit channel is missing`],
    correctAnswer: 3,
    explanation: r`Cholera toxin causes diarrhea because high cAMP holds CFTR open, so Cl⁻ leaves the crypt cells and water follows. Without CFTR there is no Cl⁻ exit path, so little fluid is secreted even with cAMP raised. The toxin does not act on SGLT1, and SGLT1 absorbs Na⁺ with glucose instead of secreting it.`,
  },
  [r`In a FRAP experiment the bleached spot recovers only 60 percent of its fluorescence. What does the missing 40 percent represent?`]: {
    question: r`In FRAP experiments, membrane proteins A and B both recover to 70 percent of their original fluorescence. A reaches this plateau in 5 s and B in 50 s. What do the results show?`,
    options: [r`The mobile fractions are equal, and A diffuses faster than B`, r`The mobile fractions are equal, and B diffuses faster than A`, r`A has the larger mobile fraction, and both diffuse equally fast`, r`B has the larger mobile fraction, and A diffuses faster than B`],
    correctAnswer: 0,
    explanation: r`The extent of recovery gives the mobile fraction, 70 percent for both, with 30 percent immobile. The rate of recovery gives the diffusion coefficient, and A recovers ten times sooner, so A diffuses faster. The answers with unequal mobile fractions confuse the speed of recovery with its final extent.`,
  },
  [r`ATP-dependent {{c1::flippases}} keep phosphatidylserine on the inner leaflet; in apoptosis a Ca2+-activated {{c2::scramblase}} exposes it outward.`]: {
    question: r`Red blood cells are depleted of ATP while cytosolic Ca²⁺ stays low. Over several hours phosphatidylserine slowly appears on the outer leaflet. What is the best explanation?`,
    options: [r`Scramblases have stopped returning it to the inner leaflet`, r`Flippases have started carrying it to the outer leaflet`, r`Flippases have stopped returning it to the inner leaflet`, r`Scramblases need ATP to hold it on the inner leaflet`],
    correctAnswer: 2,
    explanation: r`Phosphatidylserine is kept on the inner leaflet by flippases that use ATP, so without ATP the asymmetry slowly decays. Scramblases are activated by Ca²⁺, need no ATP, and randomize lipids instead of restoring asymmetry. Flippases move phosphatidylserine inward, not outward.`,
  },
  [r`Liddle syndrome is a gain-of-function mutation of the epithelial Na+ channel {{c1::ENaC}}, giving hypertension, hypokalemia, and {{c2::low}} aldosterone.`]: {
    question: r`A young patient has hypertension and low plasma K⁺ caused by an epithelial Na⁺ channel (ENaC) that cannot be removed from the collecting duct membrane. What is the expected aldosterone level, and which drug will help?`,
    options: [r`High aldosterone; amiloride helps`, r`Low aldosterone; amiloride helps`, r`Low aldosterone; spironolactone helps`, r`High aldosterone; spironolactone helps`],
    correctAnswer: 1,
    explanation: r`This is Liddle syndrome: the overactive channel reabsorbs Na⁺ without hormonal input, the expanded volume suppresses aldosterone, and amiloride works because it blocks the channel directly. High aldosterone would describe primary hyperaldosteronism instead. Spironolactone blocks the mineralocorticoid receptor upstream, which is not driving the channel here.`,
  },
  [r`Bartter syndrome mimics a {{c1::loop}} diuretic by disabling NKCC2; Gitelman mimics a {{c2::thiazide}} by disabling the distal NaCl cotransporter.`]: {
    question: r`A patient has an inherited loss of the NaCl cotransporter of the distal convoluted tubule. Which syndrome is this, and which drug's effects does it resemble?`,
    options: [r`Bartter syndrome, resembling a thiazide`, r`Gitelman syndrome, resembling a loop diuretic`, r`Bartter syndrome, resembling a loop diuretic`, r`Gitelman syndrome, resembling a thiazide`],
    correctAnswer: 3,
    explanation: r`Loss of the distal NaCl cotransporter is Gitelman syndrome, and thiazides block that same transporter. Bartter syndrome is loss of NKCC2 in the thick ascending limb, which is the target of loop diuretics. The mixed answers pair a syndrome with the drug class that acts on the other segment.`,
  },
  [r`The Na+/K+ ATPase consumes roughly {{c1::20-30 percent}} of a typical cell's ATP, and as much as {{c2::70 percent}} in neurons.`]: {
    question: r`A typical non-neuronal cell uses 1,000 units of ATP per minute. Its Na⁺/K⁺ ATPase is then blocked completely. To about what value does ATP use fall at first?`,
    options: [r`About 750 units per minute`, r`About 300 units per minute`, r`About 500 units per minute`, r`About 980 units per minute`],
    correctAnswer: 0,
    explanation: r`The pump accounts for roughly 20 to 30 percent of a typical cell's ATP use, so blocking it lowers consumption to about 750 units. A fall to 300 units would fit a neuron, where the pump can take about 70 percent. 500 units overstates the pump's share for an ordinary cell, and 980 units treats this major cost as trivial.`,
  },
  [r`An open ion channel passes about {{c1::$10^{7}$}} ions per second, while a carrier turns over only about {{c2::$10^{3}$}} solutes per second.`]: {
    question: r`One open ion channel passes ions at its typical rate. Using the typical turnover rate of a carrier protein, roughly how many carriers would it take to match the flux through that single channel?`,
    options: [r`About $10^{3}$ carriers`, r`About $10^{7}$ carriers`, r`About $10^{4}$ carriers`, r`About $10^{2}$ carriers`],
    correctAnswer: 2,
    explanation: r`An open channel passes about $10^{7}$ ions per second and a carrier turns over about $10^{3}$ solutes per second, so matching one channel takes about $10^{7}/10^{3} = 10^{4}$ carriers. $10^{3}$ is the carrier's turnover rate, not the count, and $10^{7}$ is the channel's rate. $10^{2}$ would assume carriers work at $10^{5}$ per second.`,
  },
  [r`Why is sweat chloride high in cystic fibrosis when CFTR failure elsewhere produces thick, dehydrated secretions?`]: {
    question: r`Which pairing gives the normal direction of Cl⁻ movement through CFTR in the sweat duct and in the airway epithelium?`,
    options: [r`Sweat duct: cells into lumen. Airway: lumen into cells`, r`Sweat duct: lumen into cells. Airway: cells into lumen`, r`Sweat duct: lumen into cells. Airway: lumen into cells`, r`Sweat duct: cells into lumen. Airway: cells into lumen`],
    correctAnswer: 1,
    explanation: r`In the sweat duct CFTR reabsorbs Cl⁻ from the lumen, so its loss leaves salt in the sweat. In the airway CFTR secretes Cl⁻ into the lumen with water following, so its loss dries the mucus. The other pairings reverse one or both directions and could not explain salty sweat together with dehydrated secretions.`,
  },
  [r`A drug that blocks a cardiac K+ channel prolongs the QT interval. Which phase is affected, and why is that dangerous?`]: {
    question: r`A new antibiotic turns out to block the delayed rectifier K⁺ channels of ventricular muscle. What happens to the ventricular action potential?`,
    options: [r`It shortens, because phase 3 repolarization is faster`, r`It lengthens, because the phase 0 upstroke is slowed`, r`It shortens, because the phase 2 plateau is abolished`, r`It lengthens, because phase 3 repolarization is slowed`],
    correctAnswer: 3,
    explanation: r`Phase 3 repolarization depends on K⁺ leaving through delayed rectifier channels, so blocking them delays repolarization and lengthens the action potential, seen as a long QT interval. Less K⁺ efflux cannot speed repolarization or shorten the action potential. The phase 0 upstroke is carried by Na⁺ channels, which the drug does not affect.`,
  },
  [r`Cholesterol buffers fluidity: above the transition temperature it {{c1::decreases}} fluidity, and below it, it {{c2::prevents tight packing}}.`]: {
    question: r`Artificial membranes are made from the same phospholipid with and without cholesterol, then tested above and below the lipid's transition temperature. Compared with the cholesterol-containing membrane, the cholesterol-free membrane is:`,
    options: [r`more fluid when warm and more rigid when cold`, r`less fluid when warm and more rigid when cold`, r`more fluid when warm and more fluid when cold`, r`less fluid when warm and more fluid when cold`],
    correctAnswer: 0,
    explanation: r`Cholesterol buffers fluidity: above the transition temperature it restrains chain motion, and below it its bulk prevents tight packing. Taking it away therefore gives a membrane that is more fluid when warm and that packs into a rigid gel when cold. The other answers get the effect wrong at one temperature or at both.`,
  },
  [r`Single-channel patch clamp shows square, all-or-none current steps rather than a smoothly graded current. What does that reveal?`]: {
    question: r`Raising the agonist concentration doubles the total current through a cell's ligand-gated channels. What would single-channel patch clamp recordings show at the higher concentration?`,
    options: [r`Steps of twice the size, with channels open as often as before`, r`Steps of the same size, with channels open as often as before`, r`Steps of the same size, with channels open more of the time`, r`A smooth current that rises as each pore gradually widens`],
    correctAnswer: 2,
    explanation: r`A channel is either fully open or fully closed, so each opening passes the same current, and total current rises because open probability increases. Doubled step size would mean the pore conducts more per opening, which gating does not do. Unchanged steps and unchanged open time could not double the current, and pores do not open partway.`,
  },
  [r`A patient with dilute urine fails to concentrate it after desmopressin. Is the lesion central or nephrogenic, and where does it sit?`]: {
    question: r`A patient passes large volumes of dilute urine. After a dose of desmopressin, urine osmolality rises from 150 to 600 mOsm/kg. What is the diagnosis, and where is the defect?`,
    options: [r`Central diabetes insipidus: renal V2 receptors have failed`, r`Central diabetes insipidus: pituitary ADH release has failed`, r`Nephrogenic diabetes insipidus: renal V2 receptors have failed`, r`Nephrogenic diabetes insipidus: aquaporin-2 insertion has failed`],
    correctAnswer: 1,
    explanation: r`A kidney that concentrates urine when given an ADH analog has working receptors and aquaporins, so the problem is missing hormone: central diabetes insipidus. In the nephrogenic form the V2 receptor or aquaporin-2 is defective and desmopressin has no effect. A V2 receptor failure is nephrogenic by definition, not central.`,
  },
  [r`Lipid rafts are ordered microdomains enriched in {{c1::cholesterol and sphingolipids}} that concentrate particular receptors and GPI-anchored proteins.`]: {
    question: r`A GPI-anchored receptor is found clustered in small ordered patches of the plasma membrane. Which treatment would be most likely to disperse these clusters?`,
    options: [r`Extracting peripheral proteins with a salt wash`, r`Removing glucose from the surrounding medium`, r`Removing the nucleus by enucleating the cells`, r`Extracting cholesterol from the plasma membrane`],
    correctAnswer: 3,
    explanation: r`Lipid rafts are ordered microdomains held together by cholesterol and sphingolipids, so pulling cholesterol out of the membrane breaks them up and scatters the proteins they concentrate. A salt wash removes peripheral proteins, not lipid-anchored ones. Glucose in the medium and the presence of a nucleus have no direct role in raft structure.`,
  },
  [r`Fusing a mouse and a human cell gave a heterokaryon whose labeled surface proteins fully intermixed within about {{c1::40 minutes}}.`]: {
    question: r`A mouse cell and a human cell with differently colored surface labels are fused at 37 °C. If the fused cell is examined only 5 minutes later, what would most likely be seen?`,
    options: [r`The two colors still largely on opposite halves, just starting to mix`, r`The two colors already spread evenly over the whole cell surface`, r`The two colors on opposite halves, where they will stay for good`, r`The two colors gone, as the labeled proteins have been degraded`],
    correctAnswer: 0,
    explanation: r`Complete intermixing by lateral diffusion took about 40 minutes at 37 °C, so at 5 minutes the two sets of proteins are still mostly on their own halves with mixing just beginning. Even spread this early would require far faster diffusion than was observed. Permanent separation contradicts the fluid mosaic model, and the labels were not lost to degradation.`,
  },
  [r`Why do severe liver disease and nephrotic syndrome cause edema, in Starling terms?`]: {
    question: r`In a capillary, hydrostatic pressure is 30 mmHg inside and 0 mmHg outside, and interstitial oncotic pressure is 5 mmHg. Liver failure lowers plasma oncotic pressure from 25 to 15 mmHg. How does the net filtration pressure change?`,
    options: [r`It falls from 10 to 0 mmHg outward`, r`It rises from 10 to 40 mmHg outward`, r`It rises from 10 to 20 mmHg outward`, r`It stays at 10 mmHg outward`],
    correctAnswer: 2,
    explanation: r`Net filtration pressure is the hydrostatic difference minus the oncotic difference: 30 - (25 - 5) = 10 mmHg before and 30 - (15 - 5) = 20 mmHg after. Less albumin means less inward pull, so more fluid is filtered and edema forms. A fall to 0 treats lower oncotic pressure as reducing filtration, 40 mmHg adds the oncotic terms instead of subtracting them, and no change ignores the albumin loss.`,
  },
}
